from __future__ import absolute_import

import logging
from taf.selenium.gnb.oam.coam.vdu import pages
from taf.selenium.gnb.oam.coam.vdu.common.exceptions import ButtonCanNotClick

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(pages.Diagnostic):
    """
    The class corresponding to diagnostic page on selenium_coam_vdu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Snapshot": SnapshotPageV21B(driver, version)})


class SnapshotPageV21B(pages.SnapshotPage):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Snapshot']

    def __init__(self, driver, version):
        super(SnapshotPageV21B, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV21B(driver, version)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanelV21B(pages.SnapshotPageViewPanel):

    def __init__(self, driver, version):
        self.version = version
        super(SnapshotPageViewPanelV21B, self).__init__(driver, version)

    def collect_snapshot_operation(self, skip_session_renewal, renewal_password, timeout):
        if self.elements_is_visible(self.locator.COLLECTION_ONGOING, timeout=5):
            raise RuntimeError("Snapshot is already ongoing")
        elem = self.driver.find_element_by_xpath(self.locator.COLLECT_SNAPSHOT_BUTTON)
        if not elem.is_enabled():
            raise ButtonCanNotClick("Collect Snapshot button is not enabled, please check")
        self.click_enabled_element(self.locator.COLLECT_SNAPSHOT_BUTTON)
        self._handle_session_renewal_pop_up(skip_session_renewal, renewal_password, timeout)
        self.wait_for_visibility(self.locator.COLLECTION_COMPLETED, timeout)
        return "Snapshot collected successfully"
